 3→/**
 4→ * `usePageTitle` is a custom hook that changes the page title to be the specified string passed in.
 5→ * When the component it's called from is unmounted, the page title will return to the default page title.
 6→ * @param title - the title to set the page title to
 7→ */
 8→export const usePageTitle = (title: string): void => {
 9→  const defaultTitle = useRef(document.title);
10→
11→  useEffect(() => {
12→    document.title = title;
13→  }, [title]);
14→
15→  useEffect(
16→    () => () => {
17→      document.title = defaultTitle.current;
18→    },
19→    [],
20→  );
21→};
