 37→// Define typing of columns' meta field
 38→// https://tanstack.com/table/v8/docs/api/core/column-def#meta
 39→declare module "@tanstack/table-core" {
 40→  // eslint-disable-next-line @typescript-eslint/no-unused-vars
 41→  interface ColumnMeta<TData extends RowData, TValue> {
 42→    search?: {
 43→      "data-cy"?: string;
 44→      placeholder?: string;
 45→    };
 46→    treeSelect?: {
 47→      "data-cy"?: string;
 48→      // Configures whether or not the tree select should be filtered to only represent values found in the table.
 49→      // Note that this may not be very performant for large tables.
 50→      filterOptions?: boolean;
 51→      options: TreeDataEntry[];
 52→    };
 53→    // Overcome react-table's column width limitations
 54→    // https://github.com/TanStack/table/discussions/4179#discussioncomment-3334470
 55→    width?: string;
 56→  }
 57→}
