import type { Meta, StoryObj } from "@storybook/react-vite";
import { expect, fn } from "storybook/test";
import { Button } from "@leafygreen-ui/button";
import Popconfirm from "./index";

const meta = {
  component: Popconfirm,
  tags: ["ai-generated"],
} satisfies Meta<typeof Popconfirm>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    children: "Are you sure you want to proceed?",
    onConfirm: fn(),
    trigger: <Button>Open popconfirm</Button>,
  },
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole("button", { name: /open popconfirm/i });
    await expect(trigger).toBeVisible();
    await userEvent.click(trigger);
    await expect(
      canvas.getByText("Are you sure you want to proceed?"),
    ).toBeVisible();
    await expect(canvas.getByRole("button", { name: /cancel/i })).toBeVisible();
    await expect(canvas.getByRole("button", { name: /yes/i })).toBeVisible();
  },
};

export const CustomConfirmText: Story = {
  args: {
    children: "Delete this item?",
    confirmText: "Delete",
    onConfirm: fn(),
    trigger: <Button>Delete</Button>,
  },
  play: async ({ canvas, userEvent }) => {
    const trigger = canvas.getByRole("button", { name: /delete/i });
    await userEvent.click(trigger);
    await expect(canvas.getByText("Delete this item?")).toBeVisible();
    await expect(
      canvas.getByRole("button", { name: /^delete$/i }),
    ).toBeVisible();
  },
};

export const ConfirmDisabled: Story = {
  args: {
    children: "This action is not available right now.",
    confirmDisabled: true,
    onConfirm: fn(),
    trigger: <Button>Confirm action</Button>,
  },
  play: async ({ canvas, userEvent }) => {
    await userEvent.click(
      canvas.getByRole("button", { name: /confirm action/i }),
    );
    await expect(
      canvas.getByText("This action is not available right now."),
    ).toBeVisible();
    await expect(canvas.getByRole("button", { name: /yes/i })).toBeDisabled();
  },
};

