    case TaskStatus.SystemFailed:
    case TaskStatus.SystemUnresponsive:
    case TaskStatus.SystemTimedOut:
      return {
        border: purple.dark3,
        fill: purple.dark2,
        text: purple.light3,
      };
    case TaskStatus.KnownIssue:
      return {
        border: red.light2,
        fill: white,
        text: red.dark2,
      };
    default:
      return {};
  }
